        time.sleep(1)  # Add small delay between connections
        conn.sendline(payload.encode())
        response = conn.recvall(timeout=2).decode()
        conn.close()
        print(f"Server response for '{payload}':")
        print(response)
        match = re.search(r'cookie: ([a-zA-Z0-9]+)', response, re.IGNORECASE)
        if match:
            return match.group(1)
    except Exception as e:
        print(f"Error with input {payload}: {str(e)}")
    return None

def test_single_input(test_input):
    cookie = get_cookie(test_input)
    if cookie:
        first_half = cookie[:64]
        second_half = cookie[64:]
        print(f"\nInput: {test_input}")
        print("Cookie:", cookie)
        print("First half:", first_half)
        print("Second half:", second_half)
        return {'input': test_input, 'cookie': cookie, 'first_half': first_half, 'second_half': second_half}
    return None

def main():
    test_cases = ['a', 'b', 'c', 'aa', 'bb', 'cc', 'aaa', 'bbb', 'ccc']
    results = []

    # Test single cases first
    for test_input in test_cases:
        result = test_single_input(test_input)
        if result:
            results.append(result)

    # Test lengths 4 to 16
    for length in range(4, 17):
        test_input = 'a' * length
        result = test_single_input(test_input)
        if result:
            results.append(result)

    # Analyze patterns
    if results:
        print("\nAnalysis:")
        print("=========")

        # Group by second half
        second_half_groups = {}
        for r in results:
            second_half = r['second_half']
            if second_half not in second_half_groups:
                second_half_groups[second_half] = []
            second_half_groups[second_half].append(r['input'])

        print("\nInputs with matching second halves:")
        for second_half, inputs in second_half_groups.items():
            if len(inputs) > 1:
                print(f"\nSecond half: {second_half}")
                print(f"Inputs: {inputs}")

if __name__ == "__main__":
